  (C.refs || []).forEach(function(r){ vals.push(r.v); });
  var mn = Math.min.apply(null, vals), mx = Math.max.apply(null, vals), pad = (mx - mn) * 0.1;
  var ticks = niceTicks(mn - pad, mx + pad, 5);
  var lo = ticks[0], hi = ticks[ticks.length - 1];
  function xp(k){ return margin.left + PW * (k / (n - 1)); }
  function yp(v){ return margin.top + PH - PH * ((v - lo) / (hi - lo)); }
  /* 1 gridlines */
  ticks.forEach(function(t){ var yy = yp(t); svg.appendChild(el("line", {x1: margin.left, x2: margin.left + PW, y1: yy, y2: yy, stroke: "#ececec", "stroke-width": 0.5})); svg.appendChild(el("text", {x: margin.left - 6, y: yy + 3, "text-anchor": "end", "font-family": F, "font-size": 8.5, fill: "#aaa"}, fmt(t, C.fmt))); });
  /* event bands */
  (C.bands || []).forEach(function(b){ var x1 = xp(b.a), x2 = xp(b.b); svg.appendChild(el("rect", {x: x1, y: margin.top, width: x2 - x1, height: PH, fill: b.color, "fill-opacity": b.op})); });
  /* 2 reference lines */
  (C.refs || []).forEach(function(r){ var ry = yp(r.v); svg.appendChild(el("line", {x1: margin.left, x2: margin.left + PW, y1: ry, y2: ry, stroke: r.color, "stroke-width": 1, "stroke-dasharray": "3,3"})); });
  /* 3 series */
  C.series.forEach(function(s){ var d = s.data.map(function(v, k){ return (k ? "L" : "M") + xp(k).toFixed(1) + " " + yp(v).toFixed(1); }).join(" "); svg.appendChild(el("path", {d: d, fill: "none", stroke: s.color, "stroke-width": s.width || 2, "stroke-dasharray": s.dash || "none", "stroke-linejoin": "round", "stroke-linecap": "round"})); });
  /* 4 axis */
  svg.appendChild(el("line", {x1: margin.left, x2: margin.left + PW, y1: margin.top + PH, y2: margin.top + PH, stroke: "#d8d8d8", "stroke-width": 1}));
  /* 5 endpoint dots and event marker lines */
  C.series.forEach(function(s){ svg.appendChild(el("circle", {cx: xp(n - 1), cy: yp(s.data[n - 1]), r: 3.5, fill: s.color})); });
  (C.events || []).forEach(function(ev){ var ex = xp(ev.i); svg.appendChild(el("line", {x1: ex, x2: ex, y1: margin.top, y2: margin.top + PH, stroke: "#1a3560", "stroke-opacity": 0.4, "stroke-dasharray": "2,3", "stroke-width": 1})); });
  /* 6 pill */
  var pill = C.pill, pillText = pill.text, lastX = xp(n - 1), lastY = yp(C.series[pill.si].data[n - 1]);
  var pillW = tw(pillText, 9, pill.up) + 10, pillH = 16, pillX = lastX - pillW - 6, pillY = lastY - pillH / 2 + (pill.dy || 0);
  if (pillX < margin.left) pillX = margin.left;
  if (pillY < margin.top) pillY = margin.top + 2;
  if (pillY + pillH > margin.top + PH) pillY = margin.top + PH - pillH - 2;
  svg.appendChild(el("rect", {x: pillX, y: pillY, width: pillW, height: pillH, rx: 2, fill: "#e8a825"}));
  svg.appendChild(el("text", {x: pillX + pillW / 2, y: pillY + pillH / 2 + 3.5, "text-anchor": "middle", "font-family": F, "font-size": 9, "font-weight": 700, fill: "#111"}, pillText));
  /* 7 labels and annotations */
  for (i = 0; i < n; i++){ if (i % 3 != 0 && i != n - 1) continue; svg.appendChild(el("text", {x: xp(i), y: margin.top + PH + 15, "text-anchor": "middle", "font-family": F, "font-size": 8, fill: "#999"}, C.dates[i])); }
  (C.bands || []).forEach(function(b){ var x1 = xp(b.a), x2 = xp(b.b); svg.appendChild(el("text", {x: (x1 + x2) / 2, y: margin.top + 11, "text-anchor": "middle", "font-family": F, "font-size": 7, "font-weight": 700, fill: b.lcolor}, b.label)); });
  (C.refs || []).forEach(function(r){ if (!r.label) return; svg.appendChild(el("text", {x: margin.left + 10, y: r.below ? yp(r.v) + 12 : yp(r.v) - 10, "text-anchor": "start", "font-family": F, "font-size": 7, "font-weight": 700, fill: r.lcolor}, r.label)); });
  (C.events || []).forEach(function(ev){
    var ex = xp(ev.i), labelWidth = 0;
    ev.t.forEach(function(L){ labelWidth = Math.max(labelWidth, tw(L, 7, true)); });
    var crowded = C.events.some(function(o){ return o.i !== ev.i && Math.abs(xp(o.i) - ex) < 85; });
    var nearRight = (ex + labelWidth + 3) > (margin.left + PW);
    var offset = (crowded || nearRight) ? -3 : 3;
