  svg.appendChild(el("text", {x: pillX + pillW / 2, y: pillY + pillH / 2 + 3.5, "text-anchor": "middle", "font-family": F, "font-size": 9, "font-weight": 700, fill: "#111"}, pillText));
  /* 7 labels and annotations */
  for (i = 0; i < n; i++){ if (i % 3 != 0 && i != n - 1) continue; svg.appendChild(el("text", {x: xp(i), y: margin.top + PH + 15, "text-anchor": "middle", "font-family": F, "font-size": 8, fill: "#999"}, C.dates[i])); }
  (C.bands || []).forEach(function(b){ var x1 = xp(b.a), x2 = xp(b.b); svg.appendChild(el("text", {x: (x1 + x2) / 2, y: margin.top + 11, "text-anchor": "middle", "font-family": F, "font-size": 7, "font-weight": 700, fill: b.lcolor}, b.label)); });
